import axios from "axios";

// إنشاء نسخة من axios مع إعدادات مسبقة
const api = axios.create({
  baseURL: "http://127.0.0.1:8000/api/", // رابط الـ Backend الخاص بك
});

// إضافة "Intercepto" لإرفاق التوكن مع كل طلب بشكل آلي
api.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem("token"); // جلب التوكن من المتصفح
    if (token) {
      config.headers.Authorization = `Bearer ${token};
    `}
    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

export default api;
